import{_ as l,a0 as p,w as u,s as a,I as t,x as e,a1 as i,A as r,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"用 Linux 釋放你 Chromebook 的隱藏潛能 | LCTT x X-CMD","titleTemplate":false,"description":"用 Linux 釋放你 Chromebook 的隱藏潛能 | LCTT (202102) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Linux 釋放你 Chromebook 的隱藏潛能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Linux 釋放你 Chromebook 的隱藏潛能 | LCTT (202102) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202102/20210219 Unlock your Chromebook-s hidden potential with Linux","title":"用 Linux 釋放你 Chromebook 的隱藏潛能","tag":"202102","desc":""},"relativePath":"202102/20210219 Unlock your Chromebook-s hidden potential with Linux.md","filePath":"[post].md"}'),m={name:"202102/20210219 Unlock your Chromebook-s hidden potential with Linux.md"};function d(h,o,x,b,C,k){const n=p("Link");return u(),a("div",null,[o[31]||(o[31]=t("h1",{id:"用-linux-釋放你-chromebook-的隱藏潛能",tabindex:"-1"},[e("用 Linux 釋放你 Chromebook 的隱藏潛能 "),t("a",{class:"header-anchor",href:"#用-linux-釋放你-chromebook-的隱藏潛能","aria-label":"Permalink to “用 Linux 釋放你 Chromebook 的隱藏潛能”"},"​")],-1)),o[32]||(o[32]=t("blockquote",null,[t("p",null,"Chromebook 是令人驚歎的工具，但通過解鎖它內部的 Linux 系統，你可以讓它變得更加不同凡響。")],-1)),o[33]||(o[33]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202102/24/114254qstdq1dhj288jh1z.jpg",alt:""})],-1)),t("p",null,[o[1]||(o[1]=e("Google Chromebook 運行在 Linux 系統之上，但通常它運行的 Linux 系統對普通用户而言，並不是十分容易就能訪問得到。Linux 被用作基於開源的 ",-1)),i(n,{href:"https://www.chromium.org/chromium-os"},{default:r(()=>[...o[0]||(o[0]=[e("Chromium OS",-1)])]),_:1}),o[2]||(o[2]=e(" 運行時環境的後端技術，然後 Google 將其轉換為 Chrome OS。大多數用户體驗到的界面是一個電腦桌面，可以用來運行 Chrome 瀏覽器及其應用程序。然而，在這一切的背後，有一個 Linux 系統等待被你發現。如果你知道怎麼做，你可以在 Chromebook 上啓用 Linux，把一台可能價格相對便宜、功能相對基礎的電腦變成一個嚴謹的筆記本，獲取數百個應用和你需要的所有能力，使它成為一個通用計算機。",-1))]),o[34]||(o[34]=s('<h3 id="什麼是-chromebook" tabindex="-1">什麼是 Chromebook? <a class="header-anchor" href="#什麼是-chromebook" aria-label="Permalink to “什麼是 Chromebook?”">​</a></h3><p>Chromebook 是專為 Chrome OS 創造的筆記本電腦，它本身專為特定的筆記本電腦型號而設計。Chrome OS 不是像 Linux 或 Windows 這樣的通用操作系統，而是與 Android 或 iOS 有更多的共同點。如果你決定購買 Chromebook，你會發現有許多不同製造商的型號，包括惠普、華碩和聯想等等。有些是為學生而設計，而另一些是為家庭或商業用户而設計的。主要的區別通常分別集中在電池功率或處理能力上。</p><p>無論你決定買哪一款，Chromebook 都會運行 Chrome OS，併為你提供現代計算機所期望的基本功能。有連接到互聯網的網絡管理器、藍牙、音量控制、文件管理器、桌面等等。</p><p><img src="https://opensource.com/sites/default/files/chromeos.png" alt="Chrome OS desktop"></p><p><em>Chrome OS 桌面截圖</em></p><p>不過，想從這個簡單易用的操作系統中獲得更多，你只需要激活 Linux。</p><h3 id="啓用-chromebook-的開發者模式" tabindex="-1">啓用 Chromebook 的開發者模式 <a class="header-anchor" href="#啓用-chromebook-的開發者模式" aria-label="Permalink to “啓用 Chromebook 的開發者模式”">​</a></h3><p>如果我讓你覺得啓用 Linux 看似簡單，那是因為它確實簡單但又有欺騙性。之所以説有欺騙性，是因為在啓用 Linux 之前，你<em>必須</em>備份數據。</p><p>這個過程雖然簡單，但它確實會將你的計算機重置回出廠默認狀態。你必須重新登錄到你的筆記本電腦中，如果你有數據存儲在 Google 雲盤帳户上，你必須得把它重新同步回計算機中。啓用 Linux 還需要為 Linux 預留硬盤空間，因此無論你的 Chromebook 硬盤容量是多少，都將減少一半或四分之一（自主選擇）。</p><p>在 Chromebook 上接入 Linux 仍被 Google 視為測試版功能，因此你必須選擇使用開發者模式。開發者模式的目的是允許軟件開發者測試新功能，安裝新版本的操作系統等等，但它可以為你解鎖仍在開發中的特殊功能。</p><p>要啓用開發者模式，請首先關閉你的 Chromebook。假定你已經備份了設備上的所有重要信息。</p><p>接下來，按下鍵盤上的 <code>ESC</code> 和 <code>⟳</code>，再按 <strong>電源鍵</strong> 啓動 Chromebook。</p><p><img src="https://opensource.com/sites/default/files/esc-refresh.png" alt="ESC and refresh buttons"></p><p><em>ESC 鍵和 ⟳ 鍵</em></p><p>當提示開始恢復時，按鍵盤上的 <code>Ctrl+D</code>。</p><p>恢復結束後，你的 Chromebook 已重置為出廠設置，且沒有默認的使用限制。</p><h3 id="開機啓動進入開發者模式" tabindex="-1">開機啓動進入開發者模式 <a class="header-anchor" href="#開機啓動進入開發者模式" aria-label="Permalink to “開機啓動進入開發者模式”">​</a></h3><p>在開發者模式下運行意味着每次啓動 Chromebook 時，都會提醒你處於開發者模式。你可以按 <code>Ctrl+D</code> 跳過啓動延遲。有些 Chromebook 會在幾秒鐘後發出蜂鳴聲來提醒你處於開發者模式，使得 <code>Ctrl+D</code> 操作幾乎是強制的。從理論上講，這個操作很煩人，但在實踐中，我不經常啓動我的 Chromebook，因為我只是喚醒它，所以當我需要這樣做的時候，<code>Ctrl+D</code> 只不過是整個啓動過程中小小的一步。</p><p>啓用開發者模式後的第一次啓動時，你必須重新設置你的設備，就好像它是全新的一樣。你只需要這樣做一次（除非你在未來某個時刻停用開發者模式）。</p><h3 id="啓用-chromebook-上的-linux" tabindex="-1">啓用 Chromebook 上的 Linux <a class="header-anchor" href="#啓用-chromebook-上的-linux" aria-label="Permalink to “啓用 Chromebook 上的 Linux”">​</a></h3><p>現在，你已經運行在開發者模式下，你可以激活 Chrome OS 中的 <strong>Linux Beta</strong> 功能。要做到這一點，請打開 <strong>設置</strong>，然後單擊左側列表中的 <strong>Linux Beta</strong>。</p><p>激活 <strong>Linux Beta</strong>，併為你的 Linux 系統和應用程序分配一些硬盤空間。在最糟糕的時候，Linux 是相當輕量級的，所以你真的不需要分配太多硬盤空間，但它顯然取決於你打算用 Linux 來做多少事。4 GB 的空間對於 Linux 以及幾百個終端命令還有二十多個圖形應用程序是足夠的。我的 Chromebook 有一個 64 GB 的存儲卡，我給了 Linux 系統 30 GB，那是因為我在 Chromebook 上所做的大部分事情都是在 Linux 內完成的。</p><p>一旦你的 <strong>Linux Beta</strong> 環境準備就緒，你可以通過按鍵盤上的<strong>搜索</strong>按鈕和輸入 <code>terminal</code> 來啓動終端。如果你還是 Linux 新手，你可能不知道當前進入的終端能用來安裝什麼。當然，這取決於你想用 Linux 來做什麼。如果你對 Linux 編程感興趣，那麼你可能會從 Bash（它已經在終端中安裝和運行了）和 Python 開始。如果你對 Linux 中的那些迷人的開源應用程序感興趣，你可以試試 GIMP、MyPaint、LibreOffice 或 Inkscape 等等應用程序。</p>',23)),t("p",null,[o[4]||(o[4]=e("Chrome OS 的 ",-1)),o[5]||(o[5]=t("strong",null,"Linux Beta",-1)),o[6]||(o[6]=e(" 模式不包含圖形化的軟件安裝程序，但 ",-1)),i(n,{href:"https://opensource.com/article/18/1/how-install-apps-linux"},{default:r(()=>[...o[3]||(o[3]=[e("應用程序可以從終端安裝",-1)])]),_:1}),o[7]||(o[7]=e("。可以使用 ",-1)),o[8]||(o[8]=t("code",null,"sudo apt install",-1)),o[9]||(o[9]=e(" 命令安裝應用程序。",-1))]),o[35]||(o[35]=s('<ul><li><code>sudo</code> 命令可以允許你使用超級管理員權限來執行某些命令（即 Linux 中的 <code>root</code>）。</li><li><code>apt</code> 命令是一個應用程序的安裝工具。</li><li><code>install</code> 是命令選項，即告訴 <code>apt</code> 命令要做什麼。</li></ul><p>你還必須把想要安裝的軟件包的名字和 <code>apt</code> 命令寫在一起。以安裝 LibreOffice 舉例:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install libreoffice</span></span></code></pre></div><p>當有提示是否繼續時，輸入 <code>y</code>（代表“確認”），然後按 <strong>回車鍵</strong>。</p><p>一旦應用程序安裝完畢，你可以像在 Chrome OS 上啓動任何應用程序一樣啓動它：只需要在應用程序啓動器輸入它的名字。</p><p>瞭解 Linux 應用程序的名字和它的包名需要花一些時間，但你也可以用 <code>apt search</code> 命令來搜索。例如，可以用以下的方法是找到關於照片的應用程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt search photo</span></span></code></pre></div><p>因為 Linux 中有很多的應用程序，所以你可以找一些感興趣的東西，然後嘗試一下！</p><h3 id="與-linux-共享文件和設備" tabindex="-1">與 Linux 共享文件和設備 <a class="header-anchor" href="#與-linux-共享文件和設備" aria-label="Permalink to “與 Linux 共享文件和設備”">​</a></h3>',9)),t("p",null,[o[11]||(o[11]=t("strong",null,"Linux Beta",-1)),o[12]||(o[12]=e(" 環境運行在 ",-1)),i(n,{href:"https://opensource.com/resources/what-are-linux-containers"},{default:r(()=>[...o[10]||(o[10]=[e("容器",-1)])]),_:1}),o[13]||(o[13]=e(" 中，因此 Chrome OS 需要獲得訪問 Linux 文件的權限。要授予 Chrome OS 與你在 Linux 上創建的文件的交互權限，請右擊要共享的文件夾並選擇 ",-1)),o[14]||(o[14]=t("strong",null,"管理 Linux 共享",-1)),o[15]||(o[15]=e("。",-1))]),o[36]||(o[36]=s('<p><img src="https://opensource.com/sites/default/files/chromeos-manage-linux-sharing.png" alt="Chrome OS Manage Linux sharing interface"></p><p><em>Chrome OS 的 Linux 管理共享界面</em></p><p>你可以通過 Chrome OS 的 <strong>設置</strong> 程序來管理共享設置以及其他設置。</p><p><img src="https://opensource.com/sites/default/files/chromeos-beta-linux.png" alt="Chrome OS Settings menu"></p><p><em>Chrome OS 設置菜單</em></p><h3 id="學習-linux" tabindex="-1">學習 Linux <a class="header-anchor" href="#學習-linux" aria-label="Permalink to “學習 Linux”">​</a></h3><p>如果你肯花時間學習 Linux，你不僅能夠解鎖你 Chromebook 中隱藏的潛力，還能最終學到很多關於計算機的知識。Linux 是一個有價值的工具，一個非常有趣的玩具，一個通往比常規計算更令人興奮的事物的大門。去了解它吧，你可能會驚訝於你自己和你 Chromebook 的無限潛能。</p><hr>',8)),t("p",null,[o[17]||(o[17]=e("源自: ",-1)),i(n,{href:"https://opensource.com/article/21/2/chromebook-linux"},{default:r(()=>[...o[16]||(o[16]=[e("https://opensource.com/article/21/2/chromebook-linux",-1)])]),_:1})]),t("p",null,[o[22]||(o[22]=e("作者：",-1)),i(n,{href:"https://opensource.com/users/seth"},{default:r(()=>[...o[18]||(o[18]=[e("Seth Kenlon",-1)])]),_:1}),o[23]||(o[23]=e(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:r(()=>[...o[19]||(o[19]=[e("lujun9972",-1)])]),_:1}),o[24]||(o[24]=e(" 譯者：",-1)),i(n,{href:"https://github.com/max27149"},{default:r(()=>[...o[20]||(o[20]=[e("max27149",-1)])]),_:1}),o[25]||(o[25]=e(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:r(()=>[...o[21]||(o[21]=[e("wxy",-1)])]),_:1})]),t("p",null,[o[28]||(o[28]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[26]||(o[26]=[e("LCTT",-1)])]),_:1}),o[29]||(o[29]=e(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:r(()=>[...o[27]||(o[27]=[e("Linux中國",-1)])]),_:1}),o[30]||(o[30]=e(" 榮譽推出",-1))])])}const S=l(m,[["render",d]]);export{f as __pageData,S as default};
